#[no_mangle]pub unsafe extern "C" fn wprt_dsp_meta_get(inst:u16,ext:bool)->i32{if ext{EXT_TABLE[if inst>>12==3{(inst&127)as usize}else{(inst&255)as usize}]}else{MAIN_TABLE[inst as usize]}}
// port of InitInstructionTable:no invented once-guard;source resets EXT before MAIN on every call.
#[no_mangle]pub unsafe extern "C" fn wprt_dsp_meta_init(){for i in 0..256{EXT_TABLE[i]=-2;let id=wprt_dsp_meta_find_opcode(i as u16,true);if id!=-1{EXT_TABLE[i]=id;}}for i in 0..65536{MAIN_TABLE[i]=-2;}for i in 0..65536{let id=wprt_dsp_meta_find_opcode(i as u16,false);if id!=-1{MAIN_TABLE[i]=id;}}}
// port of pdname:source names first,otherwise the exact ASCII 0x%04x result (all u16 cases compared).
#[no_mangle]pub unsafe extern "C" fn wprt_dsp_meta_pdname(v:u16,out:*mut u8)->*const c_char{for row in LABELS{if row.addr==v{return row.name;}}let hex=b"0123456789abcdef";let b=[b'0',b'x',hex[(v>>12)as usize],hex[((v>>8)&15)as usize],hex[((v>>4)&15)as usize],hex[(v&15)as usize],0];std::ptr::copy_nonoverlapping(b.as_ptr(),out,b.len());out.cast()}
// port of pdregname/pdregnamelong:valid original index contract;no invented out-of-range fallback.
#[no_mangle]pub unsafe extern "C" fn wprt_dsp_meta_regname(v:i32,long:bool)->*const c_char{let row=&*REGS.as_ptr().add(v as usize);if long{row.description}else{row.name}}
